-- 1. Update System Settings (Purge fake CRN, VAT & Address, Remove Klarna)
UPDATE `system_settings` SET `setting_value` = '' WHERE `setting_key` IN ('company_number', 'vat_number');
UPDATE `system_settings` SET `setting_value` = 'Mainland UK Logistics & Online Order Fulfillment' WHERE `setting_key` = 'registered_address';
UPDATE `system_settings` SET `setting_value` = 'Contemporary Living • Exceptional Quality Furniture' WHERE `setting_key` = 'site_tagline';
UPDATE `system_settings` SET `setting_value` = 'SAN Furniture' WHERE `setting_key` = 'company_name';
DELETE FROM `system_settings` WHERE `setting_key` IN ('klarna_enabled', 'klarna_merchant_id');

-- 2. Update Furniture Specifications (Neutralize Fire Safety Standard)
ALTER TABLE `furniture_specs` ALTER COLUMN `fire_safety_standard` SET DEFAULT 'UK Quality Checked';
UPDATE `furniture_specs` SET `fire_safety_standard` = 'UK Quality Checked' WHERE `fire_safety_standard` LIKE '%BS 5852%' OR `fire_safety_standard` = 'BS-UK-STATUTORY';

