-- 4. Clean Admin Audit Logs & Notifications
UPDATE `notifications` SET `message` = REPLACE(`message`, '14-day statutory return request', 'return request') WHERE `message` LIKE '%14-day statutory%';
UPDATE `admin_audit_logs` SET `details_json` = REPLACE(`details_json`, 'klarna_', 'payment_') WHERE `details_json` LIKE '%klarna%';
UPDATE `admin_audit_logs` SET `details_json` = REPLACE(`details_json`, 'Klarna', 'Stripe') WHERE `details_json` LIKE '%Klarna%';
